// Capture and structure error context
const errData = $input.first().json;

const workflow = errData.workflow || {};
const execution = errData.execution || {};
const error = execution.error || errData.error || {};

const incident = {
  incident_id: `inc_${Date.now()}`,
  severity: 'P1',
  service: 'instagram-content-engine',
  account: 'avalia_solar',
  workflow_name: workflow.name || 'Unknown',
  workflow_id: workflow.id,
  execution_id: execution.id,
  failed_node: execution.lastNodeExecuted || error.node?.name || 'Unknown',
  error_message: error.message || 'An unexpected error occurred in automation pipeline',
  error_stack: error.stack ? error.stack.slice(0, 1000) : null,
  timestamp: new Date().toISOString()
};

return [{
  json: incident
}];

// Acknowledge incident logging
return [{
  json: {
    status: 'INCIDENT_DISPATCHED',
    incident_id: $json.incident_id,
    recorded_at: new Date().toISOString()
  }
}];
